void UItemHolderComponent::PlayMetasound(EItemType ItemType) const
{
    switch (ItemType)
    {
    case EItemType::CreamPie:
        if (PickupSound_CreamPie)
            UGameplayStatics::PlaySound2D(this, PickupSound_CreamPie);
        break;
    case EItemType::Handpin:
        if (PickupSound_HandPin)
            UGameplayStatics::PlaySound2D(this, PickupSound_HandPin);
        break;
    case EItemType::Tabasco:
        if (PickupSound_Tabasco)
            UGameplayStatics::PlaySound2D(this, PickupSound_Tabasco);
        break;
    case EItemType::Umbrella:
        if (PickupSound_Umbrella)
            UGameplayStatics::PlaySound2D(this, PickupSound_Umbrella);
        break;
    }
}

void UItemHolderComponent::PlayUseSound(EItemType ItemType) const
{
    switch (ItemType)
    {
    case EItemType::CreamPie:
        if (UseSound_CreamPie)
            UGameplayStatics::PlaySound2D(this, UseSound_CreamPie);
        break;
    case EItemType::Handpin:
        if (UseSound_HandPin)
            UGameplayStatics::PlaySound2D(this, UseSound_HandPin);
        break;
    case EItemType::Umbrella:
        if (UseSound_Umbrella)
            UGameplayStatics::PlaySound2D(this, UseSound_Umbrella);
        break;
    case EItemType::Tabasco:
        if (UseSound_Tabasco)
            UGameplayStatics::PlaySound2D(this, UseSound_Tabasco);
        break;
    }
}

